import { motion } from "framer-motion";
import { BILHETE, BILHETES } from "./content";
import PixelSprite from "./PixelSprite";

const DIA = 24 * 60 * 60 * 1000;

// Qual dia é hoje, contando no fuso dela (meia-noite local), pra todo dia ter um bilhete novo.
export function diaDeHoje(agora = new Date()) {
  const meiaNoite = new Date(agora.getFullYear(), agora.getMonth(), agora.getDate());
  return Math.floor((meiaNoite.getTime() - meiaNoite.getTimezoneOffset() * 60000) / DIA);
}

export function bilheteDoDia(agora = new Date()) {
  return BILHETES[diaDeHoje(agora) % BILHETES.length];
}

function Bilhetinho() {
  const hoje = new Date();
  const data = hoje.toLocaleDateString("pt-BR", { weekday: "long", day: "numeric", month: "long" });

  return (
    <motion.aside
      className="faby-bilhete"
      initial={{ opacity: 0, y: 24, rotate: -4 }}
      whileInView={{ opacity: 1, y: 0, rotate: -1.5 }}
      viewport={{ once: true, amount: 0.4 }}
      transition={{ type: "spring", stiffness: 140, damping: 16 }}
    >
      <span className="faby-fita" aria-hidden="true" />
      <p className="faby-bilhete-topo">
        <PixelSprite name="bow" size={20} className="faby-inline-sprite" />
        {BILHETE.titulo} <span className="faby-bilhete-data">{data}</span>
      </p>
      <p className="faby-bilhete-texto">{bilheteDoDia(hoje)}</p>
      <p className="faby-bilhete-rodape">{BILHETE.rodape}</p>
    </motion.aside>
  );
}

export default Bilhetinho;
