import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { FASES, SECOES } from "./content";
import PixelSprite from "./PixelSprite";
import Secao from "./Secao";

const SEGUNDO = 1000;
const MINUTO = 60 * SEGUNDO;
const HORA = 60 * MINUTO;
const DIA = 24 * HORA;

export function partes(ms) {
  const passou = Math.max(0, ms);
  return {
    dias: Math.floor(passou / DIA),
    horas: Math.floor((passou % DIA) / HORA),
    minutos: Math.floor((passou % HORA) / MINUTO),
    segundos: Math.floor((passou % MINUTO) / SEGUNDO),
  };
}

const PRIMEIRA_INICIO = new Date(FASES.primeira.inicio).getTime();
const PRIMEIRA_FIM = new Date(FASES.primeira.fim).getTime();
const AGORA_INICIO = new Date(FASES.agora.inicio).getTime();

// A primeira fase ficou congelada: só os dias inteiros entre o começo e a pausa.
export const DIAS_PRIMEIRA = Math.round((PRIMEIRA_FIM - PRIMEIRA_INICIO) / DIA);

// Cada número troca subindo, como um relojinho de flip.
function Numero({ valor, digitos = 2 }) {
  const texto = String(valor).padStart(digitos, "0");
  return (
    <span className="faby-numero" aria-label={String(valor)}>
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={texto}
          aria-hidden="true"
          initial={{ y: "70%", opacity: 0, filter: "blur(2px)" }}
          animate={{ y: "0%", opacity: 1, filter: "blur(0px)" }}
          exit={{ y: "-70%", opacity: 0, filter: "blur(2px)" }}
          transition={{ type: "spring", stiffness: 260, damping: 26 }}
        >
          {texto}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function Contador() {
  const [agora, setAgora] = useState(() => Date.now());

  useEffect(() => {
    const id = setInterval(() => setAgora(Date.now()), SEGUNDO);
    return () => clearInterval(id);
  }, []);

  const tempo = partes(agora - AGORA_INICIO);
  const miudos = [
    { valor: tempo.horas, rotulo: FASES.unidades.horas },
    { valor: tempo.minutos, rotulo: FASES.unidades.minutos },
    { valor: tempo.segundos, rotulo: FASES.unidades.segundos },
  ];

  return (
    <Secao titulo={SECOES.contador} className="faby-contador">
      <div className="faby-linha-do-tempo">
        <article className="faby-fase faby-fase-pausada">
          <header className="faby-fase-topo">
            <span className="faby-fase-rotulo">{FASES.primeira.rotulo}</span>
            <span className="faby-fase-periodo">{FASES.primeira.periodo}</span>
          </header>
          <p className="faby-fase-dias">
            <span className="faby-fase-numero">{DIAS_PRIMEIRA}</span>
            <span className="faby-fase-unidade">{FASES.unidades.dias}</span>
          </p>
          <p className="faby-fase-legenda">{FASES.primeira.legenda}</p>
          <motion.span
            className="faby-carimbo"
            aria-hidden="true"
            initial={{ opacity: 0, scale: 2.4, rotate: -8 }}
            whileInView={{ opacity: 0.85, scale: 1, rotate: 9 }}
            viewport={{ once: true, margin: "0px 0px -25% 0px" }}
            transition={{ type: "spring", stiffness: 380, damping: 18, delay: 0.35 }}
          >
            {FASES.primeira.selo}
          </motion.span>
        </article>

        <p className="faby-pausa">
          <span className="faby-pausa-linha" aria-hidden="true" />
          <span className="faby-pausa-texto">{FASES.pausa}</span>
          <span className="faby-pausa-linha" aria-hidden="true" />
        </p>

        <article className="faby-fase faby-fase-agora">
          <span className="faby-fase-selo">{FASES.agora.selo}</span>
          <p className="faby-contador-titulo">{FASES.agora.titulo}</p>

          <p className="faby-contador-dias">
            <span className="faby-contador-numero">
              <Numero valor={tempo.dias} digitos={1} />
            </span>
            <span className="faby-contador-unidade">{FASES.unidades.dias}</span>
          </p>

          <div className="faby-contador-miudos">
            {miudos.map((m) => (
              <div className="faby-contador-caixa" key={m.rotulo}>
                <span className="faby-contador-caixa-valor">
                  <Numero valor={m.valor} />
                </span>
                <span className="faby-contador-caixa-rotulo">{m.rotulo}</span>
              </div>
            ))}
          </div>

          <p className="faby-contador-desde">
            <PixelSprite name="strawberry" size={16} className="faby-inline-sprite" />
            {FASES.agora.desde}
          </p>
          <p className="faby-contador-rodape">{FASES.agora.rodape}</p>
        </article>
      </div>

      <p className="faby-total">
        <PixelSprite name="heart" size={14} className="faby-inline-sprite" />
        {FASES.total(DIAS_PRIMEIRA + tempo.dias)}
      </p>
    </Secao>
  );
}

export default Contador;
