import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { CASINHA, SECOES } from "./content";
import PixelSprite from "./PixelSprite";
import Secao from "./Secao";

const EASE = [0.16, 1, 0.3, 1];

function Janela({ janela, aberta, onAbrir, indice }) {
  return (
    <button
      type="button"
      className={`faby-janela ${aberta ? "is-aberta" : ""}`}
      onClick={onAbrir}
      aria-pressed={aberta}
      aria-label={aberta ? janela.texto : `abrir a janelinha ${indice + 1}`}
    >
      <span className="faby-janela-vidro">
        <motion.span
          className="faby-janela-bicho"
          initial={false}
          animate={aberta ? { y: 0, opacity: 1, scale: 1 } : { y: 10, opacity: 0, scale: 0.6 }}
          transition={{ type: "spring", stiffness: 300, damping: 16, delay: aberta ? 0.18 : 0 }}
        >
          <PixelSprite name={janela.sprite} size={30} />
        </motion.span>
      </span>
      <span className="faby-janela-folha faby-janela-folha-esq" aria-hidden="true" />
      <span className="faby-janela-folha faby-janela-folha-dir" aria-hidden="true" />
      <span className="faby-janela-floreira" aria-hidden="true" />
    </button>
  );
}

// Uma casinha de bonecas estilo sylvanian families. Cada janela guarda uma coisa nossa,
// e a porta só abre quando todas as janelinhas já foram abertas.
function Casinha() {
  const [abertas, setAbertas] = useState([]);
  const [ultima, setUltima] = useState(null);
  const [porta, setPorta] = useState(false);

  const todas = abertas.length === CASINHA.janelas.length;

  const abrir = (i) => {
    setAbertas((a) => (a.includes(i) ? a : [...a, i]));
    setUltima(i);
  };

  const abrirPorta = () => {
    if (!todas) {
      setUltima("fechada");
      return;
    }
    setPorta(true);
    setUltima("porta");
  };

  const legenda =
    ultima === "porta"
      ? CASINHA.porta
      : ultima === "fechada"
        ? CASINHA.portaFechada
        : ultima !== null
          ? CASINHA.janelas[ultima].texto
          : CASINHA.dica;

  return (
    <Secao titulo={SECOES.casinha} className="faby-casinha-secao">
      <div className="faby-casinha">
        <div className="faby-chamine" aria-hidden="true">
          <span className="faby-fumaca">♡</span>
          <span className="faby-fumaca">♡</span>
          <span className="faby-fumaca">♡</span>
        </div>
        <div className="faby-telhado" aria-hidden="true">
          <span className="faby-telhado-janelinha" />
        </div>

        <div className="faby-parede">
          <div className="faby-janelas">
            {CASINHA.janelas.map((janela, i) => (
              <Janela
                key={janela.texto}
                janela={janela}
                indice={i}
                aberta={abertas.includes(i)}
                onAbrir={() => abrir(i)}
              />
            ))}
          </div>

          <button
            type="button"
            className={`faby-porta ${porta ? "is-aberta" : ""} ${todas && !porta ? "is-pronta" : ""}`}
            onClick={abrirPorta}
            aria-label={porta ? CASINHA.porta : "abrir a portinha"}
          >
            <span className="faby-porta-dentro">
              <motion.span
                initial={false}
                animate={porta ? { y: 0, opacity: 1 } : { y: 16, opacity: 0 }}
                transition={{ type: "spring", stiffness: 240, damping: 15, delay: porta ? 0.25 : 0 }}
              >
                <PixelSprite name="coelhinha" size={40} alt="coelhinha" />
              </motion.span>
            </span>
            <span className="faby-porta-folha" aria-hidden="true">
              <span className="faby-porta-coracao">♥</span>
            </span>
          </button>
        </div>
        <div className="faby-gramado" aria-hidden="true" />
      </div>

      <div className="faby-casinha-legenda" aria-live="polite">
        <AnimatePresence mode="wait" initial={false}>
          <motion.p
            key={legenda}
            initial={{ opacity: 0, y: 10, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.97 }}
            transition={{ duration: 0.35, ease: EASE }}
          >
            {legenda}
          </motion.p>
        </AnimatePresence>
      </div>
    </Secao>
  );
}

export default Casinha;
